<summary>Tool script to locate close by vertexes and center them in the scene view</summary>

```
@tool
class_name NavRegion
extends NavigationRegion2D

# if you cannot find the bad polygon, increase _dist and try again!
const _dist: float = 0.7
const _dist_sqr: float = pow(_dist, 2)
var _center_pair: int = 0

@export_tool_button("Locate Suspicious Map Vertices") var lme: Callable = locate_map_errors
func locate_map_errors() -> void:
	var count: int = 0
	var vertices: PackedVector2Array = navigation_polygon.get_vertices()
	var suspicious: Array[Vector2] = []
	for i: int in range(vertices.size() - 1, -1, -1):
		for v: int in range(vertices.size() - 2, -1, -1):
			if vertices[i].distance_squared_to(vertices[v]) < _dist_sqr:
				suspicious.append(vertices[i])
				count += 1
		vertices.remove_at(i)

	print("\n\nSuspicious vertices at:")
	for s: Vector2 in suspicious:
		print(s)

	if count == 0:
		print("Didn't find any closeby vertexes.")

	if count > 0:
		_center_pair = (_center_pair + 1) % count
		_center_editor_view_to_point(suspicious[_center_pair])


